```python
from typing import Protocol

class Drawable(Protocol):
    def draw(self) -> None: ...

class Circle:                 # НЕ наследуется от Drawable
    def draw(self) -> None: print("○")

def render(obj: Drawable) -> None:
    obj.draw()

render(Circle())    # mypy доволен: у Circle есть draw()
