Патчьте имя **там, где оно используется**, а не где определено.

```python
def bubble_sort(a):                      # O(n²) — учебная
    a = a[:]
    for i in range(len(a)):
        for j in range(len(a) - 1 - i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
    return a

def merge_sort(a):                       # O(n log n)
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    left, right = merge_sort(a[:mid]), merge_sort(a[mid:])
    result, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    return result + left[i:] + right[j:]

def quick_sort(a):                       # O(n log n) в среднем
    if len(a) <= 1:
        return a
    pivot = a[len(a) // 2]
    return (quick_sort([x for x in a if x < pivot])
            + [x for x in a if x == pivot]
            + quick_sort([x for x in a if x > pivot]))
```
На практике всегда используйте встроенный `sorted()` — он стабильный и очень быстрый.

```python
graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}

def bfs(graph, start):                   # обход в ширину — кратчайший путь в невзвешенном графе
    visited, queue = {start}, deque([start])
    while queue:
        node = queue.popleft()
        yield node
        for nb in graph[node]:
            if nb not in visited:
                visited.add(nb); queue.append(nb)

def dfs(graph, node, visited=None):      # обход в глубину
    visited = visited if visited is not None else set()
    visited.add(node)
    for nb in graph[node]:
        if nb not in visited:
            dfs(graph, nb, visited)
    return visited

def dijkstra(graph, start):              # graph: {u: [(v, вес), ...]}
    dist = {start: 0}
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float("inf")):
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist
```

